export const collisionLevelInstances = collisionRuntimeModule.levelInstances.map((entry) => ({
	id: entry.id,
	prefabId: entry.prefabId,
	stableId: entry.stableId,
	...(entry.transform === undefined ? {} : { transform: entry.transform }),
	...(entry.colliderComponent === undefined
		? {}
		: { components: { Collider: entry.colliderComponent } }),
})) satisfies readonly LevelPrefabInstance[];

export const collisionReadiness = collisionRuntimeModule.readiness;

export function getCollisionPrefabCollider(
	prefabId: string,
): CollisionCookRuntimeModuleData["prefabColliders"][number]["colliderComponent"] {
	const entry = collisionRuntimeModule.prefabColliders.find(
		(item) => item.prefabId === prefabId,
	);

	if (!entry) {
		throw new Error(
			`Generated collision runtime module is missing prefab collider "${prefabId}".`,
		);
	}

	return entry.colliderComponent;
}
